 assert.ok(parity.maxAudioDifference<.000003,JSON.stringify(parity))
 const current=store.read(d.id),afterOutput=mediaRecord(await execute({operation:'render',draftId:d.id,expectedRevision:current.revision})),afterId=String(mediaRecord(afterOutput.export).artifactId)
 const encoded=await script<{maxMeanPixels:number;maxAudioDifference:number}>(`(async()=>{
  const {Input,BufferSource,ALL_FORMATS,CanvasSink,AudioBufferSink}=await import('mediabunny'),inputs=[];
  try{for(const item of ${JSON.stringify([beforeId,afterId].map(id=>({id,size:fs.statSync(path.join(artifacts,id)).size})))}){const data=await window.bmwStudio.read(${JSON.stringify(project.id)},item.id,0,item.size);inputs.push(new Input({source:new BufferSource(data),formats:ALL_FORMATS}))}const video=await Promise.all(inputs.map(i=>i.getPrimaryVideoTrack())),audio=await Promise.all(inputs.map(i=>i.getPrimaryAudioTrack())),sinks=video.map(t=>new CanvasSink(t,{poolSize:1}));let maxMeanPixels=0;
   for(const time of [.1,.6,1.16,1.17,1.3,1.7,2.51,2.52,2.9,3.9,4.1,6.9]){const pixels=[];for(const sink of sinks){const frame=await sink.getCanvas(time);if(!frame)throw new Error('Missing encoded frame');const c=document.createElement('canvas');c.width=640;c.height=360;const x=c.getContext('2d');x.drawImage(frame.canvas,0,0);pixels.push(x.getImageData(0,0,640,360).data)}let sum=0;for(let i=0;i<pixels[0].length;i++)sum+=Math.abs(pixels[0][i]-pixels[1][i]);maxMeanPixels=Math.max(maxMeanPixels,sum/pixels[0].length)}
   const pcm=[];for(const track of audio){const samples=new Float32Array(7*48000);for await(const chunk of new AudioBufferSink(track).buffers(0,7)){const start=Math.round(chunk.timestamp*48000),values=chunk.buffer.getChannelData(0);for(let i=0;i<values.length;i++)if(start+i>=0&&start+i<samples.length)samples[start+i]=values[i]}pcm.push(samples)}let maxAudioDifference=0;for(let i=0;i<pcm[0].length;i++)maxAudioDifference=Math.max(maxAudioDifference,Math.abs(pcm[0][i]-pcm[1][i]));return {maxMeanPixels,maxAudioDifference};
  }finally{inputs.forEach(i=>i.dispose())}
 })()`)
 assert.ok(encoded.maxMeanPixels<1.5,JSON.stringify(encoded));assert.ok(encoded.maxAudioDifference<.002,JSON.stringify(encoded));assert.equal(crypto.createHash('sha256').update(fs.readFileSync(path.join(artifacts,sourceId))).digest('hex'),sourceSha)
