async function verifyProductionRecovery(store:VideoStudioStore,execute:(request:unknown,signal?:AbortSignal)=>Promise<unknown>):Promise<void>{
 const narrate=media.narrate,compose=media.compose,proof=process.env.BMW_VALIDATION_DIR??'.bmw-runtime/studio-validation'
 fs.mkdirSync(proof,{recursive:true})
 const digest=(id:string)=>crypto.createHash('sha256').update(fs.readFileSync(path.join(artifacts,id))).digest('hex')
 const cases:unknown[]=[]
 try{
 for(const scenario of ['provider-failure','speech-cancel','speech-cas','render-cancel','render-cas'] as const){
  media.narrate=narrate;media.compose=compose
  let d=store.create('制作恢复 '+scenario);d.width=640;d.height=360;d.fps=12;d.music=false;d.style='minimal';d.tts={provider:'local-matcha',voice:'local-zh-en',ratePercent:0}
  d.scenes=[0,1,2].map(index=>({...newStudioScene('recover-'+scenario+'-'+index,'镜头 '+(index+1)),durationSeconds:2,imageArtifactId:'source.png',narration:'原脚本 '+index,audioText:'原脚本 '+index,audioArtifactId:'voice.wav',audioDurationSeconds:1,audioGeneration:{kind:'imported' as const},captions:[{startSeconds:.5,endSeconds:1.5,text:'人工字幕 '+index,translationText:'Edited caption '+index,translationOrigin:'user-edited' as const}]}))
  d=store.update(d.id,d.revision,d,true,true)
  const old=mediaRecord(await execute({operation:'render',draftId:d.id,expectedRevision:d.revision})),oldId=String(mediaRecord(old.export).artifactId),oldSha=digest(oldId)
  d=store.read(d.id);d.scenes[1].narration='待更新脚本 1';d.scenes[2].narration='待更新脚本 2';d=store.update(d.id,d.revision,d)
  const original=structuredClone(d),requested:string[]=[];let interrupted=true,blocked=false,aborted=false,release:undefined|(()=>void),created:undefined|{artifactId:string;verificationArtifactId?:string},renders=0
  const held=(signal:AbortSignal|undefined,cancel:boolean)=>new Promise<void>((resolve,reject)=>{
   if(!signal){reject(new Error('Production needs actual cancellation signal'));return}
   const onAbort=()=>{aborted=true;if(cancel)release=()=>{signal.removeEventListener('abort',onAbort);reject(new Error('Fixture cleanup drained after cancellation'))}}
   signal.addEventListener('abort',onAbort,{once:true});blocked=true
   if(!cancel)release=()=>{signal.removeEventListener('abort',onAbort);resolve()}
   if(signal.aborted)onAbort()
  })
  media.narrate=async(raw,signal)=>{
   const text=String(mediaRecord(raw).text);requested.push(text)
   if(interrupted&&requested.length===2){
    if(scenario==='provider-failure')throw new Error('Fixture provider failed at scene 3')
    if(scenario==='speech-cancel'||scenario==='speech-cas')await held(signal,scenario==='speech-cancel')
   }
   signal?.throwIfAborted()
   const artifactId='recovery-'+crypto.randomUUID()+'.wav';fs.copyFileSync(path.join(artifacts,'voice.wav'),path.join(artifacts,artifactId))
   const measured=mediaRecord(await media.processArtifact({action:'media.inspect',artifactId},signal));assert.equal(measured.durationSeconds,1)
   return {artifactId,durationSeconds:1,provider:'local-matcha',voice:'local-zh-en',ratePercent:0,text,path:path.join(artifacts,artifactId),bytes:fs.statSync(path.join(artifacts,artifactId)).size,type:'audio',contentType:'audio/wav'}
  }
  media.compose=async(raw,signal)=>{
   renders++;const result=await compose.call(media,raw,signal)
   if(interrupted&&(scenario==='render-cancel'||scenario==='render-cas')){created={artifactId:result.artifactId,...(result.verificationArtifactId?{verificationArtifactId:result.verificationArtifactId}:{})};await held(signal,false)}
   return result
  }
  await click('reload');await waitFor(()=>script(`[...document.getElementById('draft-select').options].some(o=>o.value===${JSON.stringify(d.id)})`),'Recovery draft visible '+scenario)
  await script(`document.getElementById('draft-select').value=${JSON.stringify(d.id)};document.getElementById('draft-select').dispatchEvent(new Event('change'));true`)
  await waitFor(()=>script(`document.getElementById('draft-select').value===${JSON.stringify(d.id)}&&!document.getElementById('delivery-open').disabled`),'Recovery draft selected '+scenario)
  await click('delivery-open');await waitFor(()=>script("document.getElementById('production-plan').textContent.includes('更新 2 段旁白')"),'Recovery affected-scene summary '+scenario)
  await click('export')
  if(scenario!=='provider-failure'){
   await waitFor(async()=>blocked,'Production paused at known worker phase '+scenario)
   if(scenario==='speech-cancel'||scenario==='render-cancel'){
    assert.equal(await script("(()=>{const n=document.getElementById('cancel');return !n.hidden&&n.getClientRects().length>0&&!n.disabled})()"),true,'Running production has a usable cancel control')
    await click('cancel');await waitFor(async()=>aborted,'Actual native cancellation signal '+scenario)
    assert.equal(await script("document.getElementById('export').disabled"),true,'Admission stays closed while cleanup is held')
    assert.equal(await script("document.getElementById('cancel').disabled&&document.getElementById('job-status').textContent.includes('清理')"),true,'Cancellation is visible and cannot be repeated before cleanup drains')
    const denied=await script<string>(`window.bmwStudio.command(${JSON.stringify(project.id)},{operation:'check',draftId:${JSON.stringify(d.id)},expectedRevision:${store.read(d.id).revision}}).then(()=> 'unexpected success',error=>error.message)`)
    assert.match(denied,/Finish or cancel the current Studio command/)
   }else{
    const current=store.read(d.id);current.scenes[2].title='并发校正';current.scenes[2].narration='并发校正后的脚本';store.update(current.id,current.revision,current)
   }
   assert.ok(release,'Controlled worker has a release handle');release!()
  }
  await waitFor(()=>script("!document.getElementById('export').disabled&&/制作未完成|制作已停止/.test(document.getElementById('status').textContent)"),'Interrupted pipeline fully settled '+scenario)
  assert.equal(await script("document.getElementById('status').textContent.includes('再次确认制作')&&!document.getElementById('status').textContent.includes('Error invoking remote method')"),true,'Recoverable user message explains explicit resume without IPC implementation text')
  const partial=store.read(d.id)
  assert.deepEqual(partial.exports,original.exports,'Interrupted job preserves the exact old output journal');assert.equal(digest(oldId),oldSha,'Old MP4 bytes stay unchanged')
  assert.equal(partial.scenes[0].audioArtifactId,original.scenes[0].audioArtifactId,'Current voice is never regenerated')
  assert.equal(partial.scenes[1].audioText,'待更新脚本 1','First completed narration remains durable')
  assert.ok(partial.scenes[1].audioArtifactId?.startsWith('recovery-'));assert.deepEqual(partial.scenes.map(s=>s.captions),original.scenes.map(s=>s.captions),'Edited bilingual captions survive production failure')
  if(scenario.startsWith('speech')||scenario==='provider-failure'){assert.equal(partial.scenes[2].audioArtifactId,original.scenes[2].audioArtifactId);assert.equal(renders,0,'Speech failure never advances to encoding')}
  else {assert.equal(partial.scenes[2].audioText,'待更新脚本 2');assert.ok(created);for(const id of [created!.artifactId,created!.verificationArtifactId].filter((v):v is string=>Boolean(v)))assert.equal(fs.existsSync(path.join(artifacts,id)),false,'Uncommitted native encode and verification output are rolled back')}
  if(scenario.endsWith('cas')){assert.equal(partial.scenes[2].narration,'并发校正后的脚本');assert.equal(partial.scenes[2].title,'并发校正')}
  const beforeResume=requested.length,retained=partial.scenes[1].audioArtifactId
  fs.writeFileSync(path.join(proof,scenario+'-interrupted.png'),(await captureRendererEvidence(studio)).toPNG())
  interrupted=false;blocked=false;release=undefined
  await click('export');await waitFor(async()=>store.read(d.id).exports.length===2,'Explicit resume creates exactly one new result '+scenario)
  await waitFor(()=>script("!document.getElementById('export').disabled&&document.querySelector('#export-preview video')?.readyState>=2"),'Resumed MP4 actually decoded '+scenario)
  const completed=store.read(d.id),remaining=scenario==='render-cancel'?0:1
  assert.equal(requested.length,beforeResume+remaining,'Explicit resume processes only stale narration');assert.equal(completed.scenes[1].audioArtifactId,retained);assert.equal(digest(oldId),oldSha)
  if(remaining)assert.equal(requested.at(-1),completed.scenes[2].narration)
  const final=completed.exports.at(-1)!;assert.ok(final.verificationArtifactId);const receipt=JSON.parse(fs.readFileSync(path.join(artifacts,final.verificationArtifactId!),'utf8')) as {status:string;frames:number;tracks:{codec:string}[]}
  assert.equal(receipt.status,'passed');assert.equal(receipt.frames,72);assert.deepEqual(receipt.tracks.map(t=>t.codec).sort(),['aac','avc'])
  fs.copyFileSync(path.join(artifacts,final.artifactId),path.join(proof,scenario+'-resumed.mp4'))
  const result={scenario,requested,partial,completed,oldSha256:oldSha,renders,aborted,cleanupAdmissionHeld:scenario.endsWith('cancel'),uncommittedEncodeRolledBack:scenario.startsWith('render'),resumeNarrationCount:remaining,actualH264AAC:receipt}
  cases.push(result);console.log('PASS native automatic production recovery:',scenario,'durable partial narration, old MP4, exact CAS/cancel, explicit selective resume and actual H264/AAC')
 }
 fs.writeFileSync(path.join(proof,'production-recovery.json'),JSON.stringify({status:'passed',scope:'Actual Studio DOM/IPC/FIFO, measured synthetic WAV provider fixtures, deterministic worker phase/cleanup control, real image decoding and H264/AAC export/playable video; no paid provider, acoustic accuracy, production profile or foreground mouse acceptance',cases},null,2)+'\n')
 }finally{media.narrate=narrate;media.compose=compose}
}

